"""Generated views of the registry (contested-methods table, coverage)."""

from __future__ import annotations

from dynamisbench_soccer.registry.models import Registry, coverage

HEADER = """# Contested methods

<!-- GENERATED by `dbs registry contested --write`; do not edit by hand. -->

These processing and calculation choices have more than one defensible variant in the
literature. Benchmark tasks either **fix** one variant (stated in the task) or require
the agent to **state and defend** its choice. Graders compare like with like using the
declared `method_spec` (RES-664, RES-677).

| Claim | Subjects | Metrics | Variants | Sources | Grade |
| -- | -- | -- | -- | -- | -- |
"""


def contested_markdown(reg: Registry) -> str:
    rows = []
    for c in sorted(reg.claims, key=lambda c: c.id):
        if not c.contested:
            continue
        cites = []
        for sid in c.sources:
            src = reg.sources[sid]
            ref = f"https://doi.org/{src.doi}" if src.doi else src.url
            cites.append(f"[{src.first_author} {src.year}]({ref})")
        rows.append(
            f"| {c.id} | {', '.join(c.subjects)} | {', '.join(c.metrics) or '-'} | "
            f"{'<br>'.join(f'`{v}`' for v in c.variants)} | {'; '.join(cites)} | "
            f"{c.evidence_grade} |"
        )
    return HEADER + "\n".join(rows) + "\n"


def coverage_lines(reg: Registry) -> list[str]:
    gaps = {g.subject for g in reg.gaps}
    lines = []
    for subject, n in coverage(reg).items():
        flag = " (declared gap)" if subject in gaps else ""
        lines.append(f"{subject:>24}: {n:3d} claim(s){flag}")
    return lines
